			now/1e9, now*share/1e9, float64(s.bytes)*share/1e9)
	}
	tw.Flush()
	experts := expertBytes
	if nExpert > 0 {
		experts = expertBytes * float64(nUsed) / float64(nExpert)
	}
	now := dense + experts
	fmt.Printf("decode: dense %.3f + experts %.3f = %.3f GB/token  (was %.3f, %.2fx)\n",
